// App code: placing the sheet, opening and closing it, and putting sheetScrimClass() on its ::backdrop.
import type { Example } from "../example.ts"
import { button } from "./button.ts"
import { html, type TemplateResult } from "lit-html"

export type SheetSize = "small" | "medium" | "large" | "full"

export type SheetProps = {
  id: string
  title: string
  body: string
  actions: TemplateResult[]
  size?: SheetSize
  class?: string
}

const sizes: Record<SheetSize, string> = {
  small: "w-full max-w-xs",
  medium: "w-full max-w-sm",
  large: "w-full max-w-2xl",
  full: "w-full",
}

// The panel's look only. No motion (apps animate their own panel) and no
// placement or safe-area padding (apps place the panel).
const look = "rounded-t-surface bg-surface p-5 shadow-2xl ring-1 ring-line sm:rounded-surface"

/** Apps put these classes on their own sheet panel. */
export function sheetClass(size: SheetSize = "medium"): string {
  return `${look} ${sizes[size]}`
}

/** Apps put these classes on the sheet's ::backdrop. A literal colour: a ::backdrop does not inherit theme variables. */
export function sheetScrimClass(): string {
  return "bg-black/40"
}

export function sheet(props: SheetProps): TemplateResult {
  const own = `flex flex-col gap-4 text-fg ${sheetClass(props.size)} transition-transform duration-normal ease-enter starting:translate-y-full`
  const classes = props.class === undefined ? own : `${own} ${props.class}`
  return html`<section role="dialog" aria-modal="true" aria-labelledby="${props.id}-title" class=${classes}>
    <h2 id="${props.id}-title" class="text-base font-medium">${props.title}</h2>
    <p class="text-sm text-muted">${props.body}</p>
    <div class="flex justify-end gap-2">${props.actions}</div>
  </section>`
}

export const examples: Example[] = (Object.keys(sizes) as SheetSize[]).map((size) => ({
  label: size,
  render: () =>
    sheet({
      id: `example-sheet-${size}`,
      title: "Title",
      body: "Body",
      size,
      actions: [button({ label: "Cancel", variant: "default" }), button({ label: "Confirm", variant: "primary" })],
    }),
}))
